fonctions.fr_assign_ranger():
CREATE OR REPLACE FUNCTION public.fr_assign_ranger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_walker_id uuid; v_walker_nom text;
  v_caretaker_id uuid; v_caretaker_nom text;
  v_walker_load int := 0;
  capacite_tournee constant int := 10;   -- §4.4, ajustable
begin
  -- Assignation manuelle déjà fournie (ex. admin) : on ne touche pas
  if NEW.ranger_id is not null then
    return NEW;
  end if;

  select id, prenom into v_walker_id, v_walker_nom
    from public.staff where role = 'walker' and coalesce(actif, true) order by id limit 1;
  select id, prenom into v_caretaker_id, v_caretaker_nom
    from public.staff where role = 'caretaker' and coalesce(actif, true) order by id limit 1;

  if NEW.service = 'walking' then
    if v_walker_id is not null then
      select count(*) into v_walker_load
        from public.reservations r
       where r.ranger_id = v_walker_id
         and r.service = 'walking'
         and r.date_debut = NEW.date_debut
         and coalesce(r.creneau, '') = coalesce(NEW.creneau, '')
         and r.statut <> 'annule';
    end if;

    if v_walker_id is not null and v_walker_load < capacite_tournee then
      NEW.ranger_id := v_walker_id;  NEW.ranger_nom := v_walker_nom;
    elsif v_caretaker_id is not null then        -- overflow : tournée pleine
      NEW.ranger_id := v_caretaker_id; NEW.ranger_nom := v_caretaker_nom;
    end if;                                        -- sinon ranger_id null -> à traiter par l'admin
  else
    if v_caretaker_id is not null then            -- daycare + boarding
      NEW.ranger_id := v_caretaker_id; NEW.ranger_nom := v_caretaker_nom;
    end if;
  end if;

  return NEW;
end;
$function$

