fonctions.fr_check_cutoff_reservation():
CREATE OR REPLACE FUNCTION public.fr_check_cutoff_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  maintenant_lux timestamp := (now() at time zone 'Europe/Luxembourg');
  jour_lux       date      := maintenant_lux::date;
  heure_lux      int       := extract(hour from maintenant_lux);
  cutoff         int       := 8;   -- heure de clôture
begin
  -- Gabriel et les rangers passent outre : saisie manuelle, rattrapage,
  -- réservation prise par téléphone.
  if public.fr_est_staff() then
    return new;
  end if;

  if new.date_debut is null then
    return new;
  end if;

  if new.date_debut < jour_lux then
    raise exception
      'FR_CUTOFF: impossible de reserver une date passee (%).', new.date_debut
      using errcode = 'check_violation';
  end if;

  if new.date_debut = jour_lux and heure_lux >= cutoff then
    raise exception
      'FR_CUTOFF: les demandes pour aujourd''hui sont closes depuis %h00. Appelez Gabriel.', cutoff
      using errcode = 'check_violation';
  end if;

  return new;
end;
$function$

fonctions.fr_check_chaleur_reservation():
CREATE OR REPLACE FUNCTION public.fr_check_chaleur_reservation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_deb date; v_fin date; v_nom text;
begin
  if new.chien_id is null then return new; end if;
  if public.fr_est_staff() then return new; end if;

  select chaleur_debut, chaleur_fin, nom into v_deb, v_fin, v_nom
    from public.chiens where id = new.chien_id;
  if v_deb is null or v_fin is null then return new; end if;

  if coalesce(new.date_fin, new.date_debut) >= v_deb and new.date_debut <= v_fin then
    raise exception
      'FR_CHALEUR: % est en mode chaleur jusqu''au %. Relancez les promenades ou choisissez une date ulterieure.',
      coalesce(v_nom, 'cette chienne'), to_char(v_fin, 'DD/MM/YYYY')
      using errcode = 'check_violation';
  end if;
  return new;
end;
$function$

