 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client_id uuid;
begin
  if p_version is null or length(trim(p_version)) = 0 then
    raise exception 'FR_CGV:version_absente';
  end if;

  select id into v_client_id from public.clients where auth_id = auth.uid() limit 1;
