fonctions.fr_imputer_client(p_client uuid):
CREATE OR REPLACE FUNCTION public.fr_imputer_client(p_client uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  p        record;
  f        record;
  v_reste  numeric(10,2);
  v_solde  numeric(10,2);
  v_part   numeric(10,2);
  v_avoir  numeric(10,2) := 0;
begin
  for p in
    select pa.id, pa.date_virement,
           pa.montant - coalesce((select sum(i.montant) from public.paiements_imputations i
                                   where i.paiement_id = pa.id), 0) as reste
      from public.paiements pa
     where pa.client_id = p_client and pa.annule_le is null
     order by pa.date_virement, pa.created_at
  loop
    v_reste := p.reste;
    continue when v_reste <= 0;
    for f in
      select fa.id, (coalesce(fa.total_ttc, 0)::numeric + fa.frais_dossier - fa.montant_paye) as solde
        from public.factures fa
       where fa.client_id = p_client and coalesce(fa.statut, 'impayee') <> 'payee'
       order by fa.date_echeance nulls last, fa.date_emission nulls last, fa.created_at
       for update
    loop
      exit when v_reste <= 0;
      v_solde := f.solde;
      continue when v_solde <= 0;
      v_part := least(v_reste, v_solde);
      insert into public.paiements_imputations (paiement_id, facture_id, montant)
      values (p.id, f.id, v_part);
      update public.factures
         set montant_paye  = montant_paye + v_part,
             statut        = case when v_solde - v_part <= 0.004 then 'payee' else statut end,
             date_paiement = case when v_solde - v_part <= 0.004 then p.date_virement else date_paiement end
       where id = f.id;
      v_reste := v_reste - v_part;
    end loop;
    v_avoir := v_avoir + greatest(v_reste, 0);
  end loop;
  return v_avoir;   -- montant resté en avoir
end $function$

fonctions.fr_invitation_lire(p_token text):
CREATE OR REPLACE FUNCTION public.fr_invitation_lire(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  inv public.invitations%rowtype;
begin
  if p_token is null or length(trim(p_token)) = 0 then
    return jsonb_build_object('statut', 'absente');
  end if;

  select * into inv from public.invitations
  where token = trim(p_token)
  order by created_at desc
  limit 1;

  if not found then
    return jsonb_build_object('statut', 'introuvable');
  elsif coalesce(inv.utilise, false) then
    return jsonb_build_object('statut', 'utilisee');
  elsif inv.expire_at is not null and inv.expire_at < now() then
    return jsonb_build_object('statut', 'expiree');
  end if;

  return jsonb_build_object(
    'statut', 'valide',
    'prenom', inv.prenom,
    'email',  lower(trim(inv.email)),
    'langue', case when inv.langue in ('fr','en','lu') then inv.langue else 'fr' end
  );
end $function$

fonctions.fr_chaleur_signaler(p_chien uuid):
CREATE OR REPLACE FUNCTION public.fr_chaleur_signaler(p_chien uuid)
 RETURNS chaleurs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid; v_nom text; v_staff uuid; v_staff_nom text; v_row public.chaleurs;
begin
  if not public.fr_est_staff() then
    raise exception 'FR_CHALEUR: reserve au staff.';
  end if;

  select client_id, nom into v_client, v_nom from public.chiens where id = p_chien;
  if v_client is null then raise exception 'FR_CHALEUR: chien introuvable.'; end if;

  if not public.fr_chaleur_eligible(p_chien) then
    raise exception
      'FR_CHALEUR: option reservee aux femelles non sterilisees. Verifiez la fiche du chien.';
  end if;

  if exists (select 1 from public.chaleurs
              where chien_id = p_chien and statut in ('signale','active')) then
    raise exception 'FR_CHALEUR: un signalement est deja en cours pour cette chienne.';
  end if;

  select id, nullif(trim(coalesce(prenom,'') || ' ' || coalesce(nom,'')), '')
    into v_staff, v_staff_nom
    from public.staff where auth_id = auth.uid() limit 1;

  insert into public.chaleurs (chien_id, statut, date_debut, date_fin,
                               declare_par, declare_auth_id, signale_par_nom)
  values (p_chien, 'signale', current_date, null, 'staff', auth.uid(), v_staff_nom)
  returning * into v_row;

  -- Message à Gabriel, dans le fil du ranger
  if v_staff is not null then
    begin
      insert into public.messages (staff_id, expediteur, contenu, lu, type)
      values (v_staff, 'staff',
        coalesce(v_nom, 'Une chienne') || ' semble etre en chaleur — constate en promenade le '
        || to_char(current_date, 'DD/MM') || '. Aucune modification du planning n''a ete faite : '
        || 'a confirmer avec le client.',
        false, 'message');
    exception when others then null;  -- messagerie staff absente : le signalement reste valable
    end;
  end if;

  -- Avis au client, dans son espace
  begin
    insert into public.messages (client_id, expediteur, contenu, lu, type)
    values (v_client, 'admin',
      'Lors de la promenade du ' || to_char(current_date, 'DD/MM') || ', '
      || coalesce(v_staff_nom, 'notre ranger')
      || ' a constate que ' || coalesce(v_nom, 'votre chienne') || ' semble etre en chaleur. '
      || 'Rien n''a ete modifie a votre planning. Vous pouvez activer le mode chaleur depuis la '
      || 'fiche de votre chienne, ou nous en parler ici.',
      false, 'notification');
  exception when others then null;
  end;

  return v_row;
end;
$function$

fonctions.fr_param_num(p_cle text, p_defaut numeri:
CREATE OR REPLACE FUNCTION public.fr_param_num(p_cle text, p_defaut numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v text;
begin
  select valeur into v from public.parametres where cle = p_cle limit 1;
  if v is null or trim(v) = '' then return p_defaut; end if;
  return replace(regexp_replace(v, '[^0-9.,-]', '', 'g'), ',', '.')::numeric;
exception when others then
  return p_defaut;
end $function$

fonctions.fr_chaleur_apercu(p_chien uuid, p_jours:
CREATE OR REPLACE FUNCTION public.fr_chaleur_apercu(p_chien uuid, p_jours integer DEFAULT 21)
 RETURNS TABLE(reservation_id uuid, date_occurrence date, service text, pourcentage integer, montant_ligne numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid; v_debut date := current_date; v_fin date;
  r public.reservations; d date; v_exclues text[]; v_unit numeric;
begin
  select client_id into v_client from public.chiens where id = p_chien;
  if v_client is null then return; end if;
  if not (public.fr_est_staff() or v_client = public.fr_mon_client_id()) then
    raise exception 'FR_CHALEUR: acces refuse.';
  end if;

  v_fin := v_debut + (coalesce(p_jours, 21) - 1);

  for r in
    select * from public.reservations
     where chien_id = p_chien
       and coalesce(statut, '') <> 'annule'
       and date_debut <= v_fin
       and coalesce(date_fin_recurrence, date_fin, date_debut) >= v_debut
  loop
    v_exclues := array(
      select trim(x) from unnest(string_to_array(coalesce(r.dates_exclues, ''), ',')) x
       where trim(x) <> ''
    );
    -- Prix unitaire estimé : montant de la ligne / nombre de séances
    v_unit := case when coalesce(r.nb_seances, 0) > 0
                   then coalesce(r.montant_ttc, 0) / r.nb_seances
                   else coalesce(r.montant_ttc, 0) end;

    for d in select * from public.fr_occurrences_resa(r, v_debut, v_fin) loop
      if not (to_char(d, 'YYYY-MM-DD') = any(v_exclues)) then
        reservation_id  := r.id;
        date_occurrence := d;
        service         := r.service;
        pourcentage     := public.fr_politique_annulation(r.service, d);
        montant_ligne   := round(v_unit * pourcentage / 100.0, 2);
        return next;
      end if;
    end loop;
  end loop;
end;
$function$

fonctions.fr_paiement_annuler(p_paiement uuid, p_m:
CREATE OR REPLACE FUNCTION public.fr_paiement_annuler(p_paiement uuid, p_motif text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid;
  i        record;
begin
  if not public.fr_est_admin() then raise exception 'FR_PAIEMENT:interdit'; end if;
  select client_id into v_client from public.paiements
   where id = p_paiement and annule_le is null for update;
  if v_client is null then raise exception 'FR_PAIEMENT:introuvable_ou_deja_annule'; end if;

  for i in select * from public.paiements_imputations where paiement_id = p_paiement loop
    update public.factures
       set montant_paye  = greatest(montant_paye - i.montant, 0),
           statut        = 'impayee',
           date_paiement = null
     where id = i.facture_id;
  end loop;
  delete from public.paiements_imputations where paiement_id = p_paiement;

  update public.paiements
     set annule_le = now(),
         note = concat_ws(' · ', note, 'Annulé' || coalesce(' : ' || nullif(trim(p_motif), ''), ''))
   where id = p_paiement;

  -- Les autres paiements du client peuvent couvrir ce qui vient de se rouvrir
  perform public.fr_imputer_client(v_client);
  -- Une facture couverte à nouveau retrouve le statut payé via l'imputation ;
  -- celle qui ne l'est plus reste « impayee ».
  return jsonb_build_object('paiement_id', p_paiement, 'client_id', v_client, 'annule', true);
end $function$

fonctions.fr_politique_annulation(p_service text,:
CREATE OR REPLACE FUNCTION public.fr_politique_annulation(p_service text, p_date date)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  maintenant timestamp := (now() at time zone 'Europe/Luxembourg');
  jours      int;
  limite     timestamp;
begin
  if p_date is null then return 100; end if;

  -- Clôture estivale : juin, juillet, août
  if extract(month from p_date)::int between 6 and 8 then
    return 100;
  end if;

  if p_service = 'boarding' then
    jours := p_date - maintenant::date;
    if jours > 30 then return 0;   end if;
    if jours >= 14 then return 50; end if;
    return 100;
  end if;

  -- Walking / Day Care : gratuit jusqu'à 9h00 la veille
  limite := (p_date - 1)::timestamp + interval '9 hours';
  if maintenant < limite then return 0; end if;
  return 100;
end;
$function$

fonctions.fr_facture_etape(p_facture text, p_etape:
CREATE OR REPLACE FUNCTION public.fr_facture_etape(p_facture text, p_etape text, p_frais boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  f        record;
  v_frais  numeric(10,2) := 0;
begin
  if not public.fr_est_admin() then raise exception 'FR_RECOUVREMENT:interdit'; end if;
  select * into f from public.factures where id::text = p_facture for update;
  if not found then raise exception 'FR_RECOUVREMENT:facture_introuvable'; end if;
  if coalesce(f.statut, 'impayee') = 'payee' then raise exception 'FR_RECOUVREMENT:facture_payee'; end if;

  if p_etape = 'rappel_1' then
    update public.factures set rappel_1_le = coalesce(rappel_1_le, now()) where id = f.id;
  elsif p_etape = 'rappel_2' then
    if f.rappel_2_le is null and p_frais then
      v_frais := public.fr_param_num('frais_rappel_impaye', 25);
    end if;
    update public.factures
       set rappel_1_le   = coalesce(rappel_1_le, now()),
           rappel_2_le   = coalesce(rappel_2_le, now()),
           frais_dossier = frais_dossier + v_frais
     where id = f.id;
  elsif p_etape = 'mise_en_demeure' then
    update public.factures set mise_en_demeure_le = coalesce(mise_en_demeure_le, now()) where id = f.id;
  else
    raise exception 'FR_RECOUVREMENT:etape_inconnue';
  end if;

  -- Un avoir éventuel couvre aussitôt les frais ajoutés
  perform public.fr_imputer_client(f.client_id);
  return jsonb_build_object('facture_id', f.id, 'etape', p_etape, 'frais_ajoutes', v_frais);
end $function$

fonctions.fr_chaleur_declarer(p_chien uuid, p_jour:
CREATE OR REPLACE FUNCTION public.fr_chaleur_declarer(p_chien uuid, p_jours integer DEFAULT 21, p_source text DEFAULT NULL::text)
 RETURNS chaleurs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_client uuid; v_nom text; v_source text;
  v_debut date := current_date; v_fin date;
  v_retirees jsonb := '[]'::jsonb; v_row public.chaleurs;
  r public.reservations; d date; v_exclues text[]; v_pct int; v_nb int := 0;
begin
  if p_jours is null or p_jours < 1 or p_jours > 60 then
    raise exception 'FR_CHALEUR: duree invalide (%). Attendu 1 a 60 jours.', p_jours;
  end if;
  v_fin := v_debut + (p_jours - 1);

  select client_id, nom into v_client, v_nom from public.chiens where id = p_chien;
  if v_client is null then raise exception 'FR_CHALEUR: chien introuvable.'; end if;

  -- Retirer des seances du planning engage la facturation : seuls
  -- Gabriel et le proprietaire peuvent le faire. Un ranger signale
  -- (fr_chaleur_signaler), il ne declare pas.
  if v_client = public.fr_mon_client_id() then
    v_source := 'client';
  elsif exists (select 1 from public.user_roles where id = auth.uid() and role = 'admin') then
    v_source := 'admin';
  elsif public.fr_est_staff() then
    raise exception
      'FR_CHALEUR: un ranger ne peut que signaler. La declaration revient au client ou a Gabriel.';
  else
    raise exception 'FR_CHALEUR: acces refuse.';
  end if;

  if not public.fr_chaleur_eligible(p_chien) then
    raise exception
      'FR_CHALEUR: option reservee aux femelles non sterilisees. Verifiez le sexe et la sterilisation sur la fiche.';
  end if;

  if exists (select 1 from public.chaleurs where chien_id = p_chien and statut = 'active') then
    raise exception 'FR_CHALEUR: cette chienne est deja en mode chaleur.';
  end if;

  -- Un signalement ranger en cours devient la declaration
  update public.chaleurs set statut = 'close', annulee_le = now(), annulee_par = v_source
   where chien_id = p_chien and statut = 'signale';

  for r in
    select * from public.reservations
     where chien_id = p_chien
       and coalesce(statut, '') <> 'annule'
       and date_debut <= v_fin
       and coalesce(date_fin_recurrence, date_fin, date_debut) >= v_debut
  loop
    v_exclues := array(
      select trim(x) from unnest(string_to_array(coalesce(r.dates_exclues, ''), ',')) x
       where trim(x) <> ''
    );

    for d in select * from public.fr_occurrences_resa(r, v_debut, v_fin) loop
      -- Deja annulee pour une autre raison : on n'y touche pas, et on
      -- ne la remettra pas non plus a l'annulation.
      if not (to_char(d, 'YYYY-MM-DD') = any(v_exclues)) then
        v_pct := public.fr_politique_annulation(r.service, d);
        v_exclues := v_exclues || to_char(d, 'YYYY-MM-DD');
        v_nb := v_nb + 1;
        v_retirees := v_retirees || jsonb_build_object(
          'reservation_id', r.id, 'date', to_char(d, 'YYYY-MM-DD'), 'pourcentage', v_pct
        );

        insert into public.annulations_occurrences
          (reservation_id, date_occurrence, annule_par, annulation_tardive, facture_pourcentage)
        values (r.id, d, 'chaleur', v_pct > 0, v_pct);
      end if;
    end loop;

    update public.reservations set dates_exclues = array_to_string(v_exclues, ',')
     where id = r.id;
  end loop;

  insert into public.chaleurs (chien_id, statut, date_debut, date_fin,
                               declare_par, declare_auth_id, dates_retirees)
  values (p_chien, 'active', v_debut, v_fin, v_source, auth.uid(), v_retirees)
  returning * into v_row;

  update public.chiens
     set chaleur_debut = v_debut, chaleur_fin = v_fin, chaleur_source = v_source
   where id = p_chien;

  -- Trace dans la messagerie : Gabriel voit passer la decision du client
  if v_source = 'client' then
    begin
      insert into public.messages (client_id, expediteur, contenu, lu, type)
      values (v_client, 'client',
        'Mode chaleur active pour ' || coalesce(v_nom, 'ma chienne') || ' jusqu''au '
        || to_char(v_fin, 'DD/MM') || ' (' || v_nb || ' seance(s) retiree(s) du planning).',
        false, 'message');
    exception when others then null;
    end;
  end if;

  return v_row;
end;
$function$

fonctions.fr_occurrences_resa(p_resa reservations,:
CREATE OR REPLACE FUNCTION public.fr_occurrences_resa(p_resa reservations, p_debut date, p_fin date)
 RETURNS SETOF date
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  jour_map constant jsonb := '{"dim":0,"lun":1,"mar":2,"mer":3,"jeu":4,"ven":5,"sam":6}'::jsonb;
  d date; borne_deb date; borne_fin date; dows int[]; j text;
begin
  if p_resa.date_debut is null then return; end if;

  if p_resa.service = 'boarding' then                 -- chaque nuit
    borne_deb := greatest(p_resa.date_debut, p_debut);
    borne_fin := least(coalesce(p_resa.date_fin, p_resa.date_debut) - 1, p_fin);
    d := borne_deb;
    while d <= borne_fin loop return next d; d := d + 1; end loop;
    return;
  end if;

  if coalesce(p_resa.jours_recurrence, '') <> '' then -- récurrence hebdomadaire
    dows := '{}';
    foreach j in array string_to_array(p_resa.jours_recurrence, ',') loop
      if jour_map ? trim(j) then dows := dows || (jour_map ->> trim(j))::int; end if;
    end loop;
    if array_length(dows, 1) is null then return; end if;

    borne_deb := greatest(p_resa.date_debut, p_debut);
    borne_fin := least(coalesce(p_resa.date_fin_recurrence, p_resa.date_fin, p_fin), p_fin);
    d := borne_deb;
    while d <= borne_fin loop
      if extract(dow from d)::int = any(dows) then return next d; end if;
      d := d + 1;
    end loop;
    return;
  end if;

  if p_resa.date_debut between p_debut and p_fin then -- séance unique
    return next p_resa.date_debut;
  end if;
end;
$function$

fonctions.fr_inscription_finaliser(p_token text, p:
CREATE OR REPLACE FUNCTION public.fr_inscription_finaliser(p_token text, p_client jsonb, p_chiens jsonb DEFAULT '[]'::jsonb, p_cgv_version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  inv            public.invitations%rowtype;
  v_email        text;
  v_auth_id      uuid;
  v_client_id    uuid;
  v_numero       integer;
  v_existant     boolean := false;
  v_a_des_chiens boolean := false;
  v_cols         text;
  v_sets         text;
  v_chien        jsonb;
  v_nb_chiens    int := 0;
  v_confirme     boolean := false;
  c_cols_client  text[] := array['prenom','nom','telephone','adresse','commune',
                                 'langue','hors_zone','personnes_autorisees'];
  c_cols_chien   text[] := array['nom','race','poids_kg','sexe','sterilise',
                                 'numero_puce','grand_chien','notes_sante','comportement','date_naissance','vaccins_ok','assurance_ok','veterinaire','veterinaire_tel','allergies','medicaments','pathologies'];
begin
  -- ── 1. Invitation, verrouillée pour toute la transaction ──
  if p_token is null or length(trim(p_token)) = 0 then
    raise exception 'FR_INSCRIPTION:token_absent';
  end if;

  select * into inv from public.invitations
  where token = trim(p_token)
  order by created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'FR_INSCRIPTION:token_introuvable';
  elsif coalesce(inv.utilise, false) then
    raise exception 'FR_INSCRIPTION:token_utilise';
  elsif inv.expire_at is not null and inv.expire_at < now() then
    raise exception 'FR_INSCRIPTION:token_expire';
  end if;

  v_email := lower(trim(inv.email));

  if coalesce(trim(p_client->>'prenom'), '') = '' or coalesce(trim(p_client->>'nom'), '') = '' then
    raise exception 'FR_INSCRIPTION:nom_obligatoire';
  end if;

  -- ── 2. Compte Auth créé par signUp() juste avant ──
  select id into v_auth_id from auth.users
  where lower(email) = v_email
  order by created_at desc
  limit 1;

  if v_auth_id is null then
    raise exception 'FR_INSCRIPTION:compte_auth_absent';
  end if;

  -- ── 3. Fiche client existante ? ──
  select id, numero_client into v_client_id, v_numero
  from public.clients
  where lower(trim(email)) = v_email
  order by numero_client nulls last
  limit 1
  for update;

  v_existant := v_client_id is not null;

  if exists (select 1 from public.clients
             where auth_id = v_auth_id
               and id is distinct from v_client_id) then
    raise exception 'FR_INSCRIPTION:compte_deja_rattache';
  end if;

  select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position),
         string_agg(format('%1$I = r.%1$I', c.column_name), ', ' order by c.ordinal_position)
    into v_cols, v_sets
  from information_schema.columns c
  where c.table_schema = 'public' and c.table_name = 'clients'
    and c.column_name = any(c_cols_client)
    and p_client ? c.column_name;

  if v_existant then
    execute format(
      'update public.clients t set %s, auth_id = $1, actif = true
         from jsonb_populate_record(null::public.clients, $2) r
        where t.id = $3', v_sets)
      using v_auth_id, p_client, v_client_id;
  else
    perform pg_advisory_xact_lock(hashtext('fr_numero_client'));
    select coalesce(max(numero_client), 1000) + 1 into v_numero
    from public.clients where numero_client < 9000;

    execute format(
      'insert into public.clients (numero_client, email, auth_id, actif, is_test, client_fidele, %1$s)
       select $1, $2, $3, true, false, false, %1$s
         from jsonb_populate_record(null::public.clients, $4)
       returning id', v_cols)
      into v_client_id
      using v_numero, v_email, v_auth_id, p_client;
  end if;

  -- ── 3 bis. Acceptation des CGV (article 3.2) ──
  if p_cgv_version is not null and length(trim(p_cgv_version)) > 0 then
    update public.clients
    set cgv_version = trim(p_cgv_version), cgv_acceptee_le = now()
    where id = v_client_id;
  end if;

  -- ── 4. Chiens ──
  select exists (select 1 from public.chiens where client_id = v_client_id)
    into v_a_des_chiens;

  if not v_a_des_chiens and jsonb_typeof(p_chiens) = 'array' then
    for v_chien in select * from jsonb_array_elements(p_chiens) loop
      continue when coalesce(trim(v_chien->>'nom'), '') = '';

      select string_agg(quote_ident(c.column_name), ', ' order by c.ordinal_position)
        into v_cols
      from information_schema.columns c
      where c.table_schema = 'public' and c.table_name = 'chiens'
        and c.column_name = any(c_cols_chien)
        and v_chien ? c.column_name;

      execute format(
        'insert into public.chiens (client_id, actif, %1$s)
         select $1, true, %1$s
           from jsonb_populate_record(null::public.chiens, $2)', v_cols)
        using v_client_id, v_chien;

      v_nb_chiens := v_nb_chiens + 1;
    end loop;
  end if;

  -- ── 5. Invitation consommée ──
  update public.invitations set utilise = true where id = inv.id;

  -- ── 6. Email confirmé : le token reçu par le client en fait foi ──
  begin
    update auth.users set email_confirmed_at = now()
    where id = v_auth_id and email_confirmed_at is null;
    v_confirme := true;
  exception when insufficient_privilege then
    v_confirme := false;
  end;

  return jsonb_build_object(
    'client_id',       v_client_id,
    'numero_client',   v_numero,
    'fiche_existante', v_existant,
    'chiens_crees',    v_nb_chiens,
    'email',           v_email,
    'email_confirme',  v_confirme,
    'cgv_version',     p_cgv_version
  );
end $function$

fonctions.fr_paiement_enregistrer(p_client uuid, p:
CREATE OR REPLACE FUNCTION public.fr_paiement_enregistrer(p_client uuid, p_date date, p_montant numeric, p_reference text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id     uuid;
  v_avoir  numeric;
  v_det    jsonb;
begin
  if not public.fr_est_admin() then raise exception 'FR_PAIEMENT:interdit'; end if;
  if p_client is null or p_date is null then raise exception 'FR_PAIEMENT:champs_obligatoires'; end if;
  if p_montant is null or p_montant <= 0 then raise exception 'FR_PAIEMENT:montant_invalide'; end if;
  if p_date > public.fr_aujourdhui() then raise exception 'FR_PAIEMENT:date_future'; end if;

  insert into public.paiements (client_id, date_virement, montant, reference, note)
  values (p_client, p_date, round(p_montant, 2), nullif(trim(p_reference), ''), nullif(trim(p_note), ''))
  returning id into v_id;

  v_avoir := public.fr_imputer_client(p_client);

  select coalesce(jsonb_agg(jsonb_build_object(
           'facture_id', f.id, 'numero', f.numero, 'montant', i.montant,
           'soldee', f.statut = 'payee',
           'reste_du', greatest(coalesce(f.total_ttc,0)::numeric + f.frais_dossier - f.montant_paye, 0))
           order by f.date_echeance), '[]'::jsonb)
    into v_det
    from public.paiements_imputations i
    join public.factures f on f.id = i.facture_id
   where i.paiement_id = v_id;

  return jsonb_build_object('paiement_id', v_id, 'imputations', v_det, 'avoir_client', v_avoir);
end $function$
